//! Generated protobuf types for the Spotify client protocol.
//!
//! The schemas are vendored from librespot (MIT); see `proto/VENDORED.md`.
//! Files without a `package` statement (`keyexchange.proto`, `authentication.proto`)
//! land at the crate root. Every other file lands under `spotify::...`, mirroring
//! its package name, for example `spotify::login5::v3::LoginRequest`.
#![allow(clippy::all, rustdoc::all)]

include!(concat!(env!("OUT_DIR"), "/_includes.rs"));
